using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor{public static class AftermathPizzaFinish{public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/PrisonAftermath.unity");EditorSceneManager.SaveScene(scene,"Logs/Aftermath-before-pizza.unity",true);var f=Object.FindFirstObjectByType<AftermathFilm>();var box=f.shots[13].motions.First(m=>!m.actor).subject;var previous=box.Find("배달할 페퍼로니 피자");if(previous)Object.DestroyImmediate(previous.gameObject);var pizza=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scripts/Mok/Resources/MokPizzaArt/PepperoniBaked.prefab"),box);pizza.name="배달할 페퍼로니 피자";pizza.transform.localPosition=new Vector3(0,.025f,0);pizza.transform.localRotation=Quaternion.identity;pizza.transform.localScale=Vector3.one*.85f;foreach(var c in pizza.GetComponentsInChildren<Collider>())Object.DestroyImmediate(c);var stages=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scripts/Mok/Resources/MokPizzaArt/PizzaStages.prefab"),pizza.transform);stages.transform.localPosition=Vector3.zero;stages.transform.localRotation=Quaternion.identity;stages.transform.localScale=Vector3.one;foreach(Transform t in stages.transform)t.gameObject.SetActive(t.name=="BakedCrust"||t.name=="MeltedCheese"||t.name=="Sauce");EditorSceneManager.SaveScene(scene);AftermathReview.Record();}}}
